messages.arguments:
{"cmd": "set -o pipefail
mkdir -p output
ssh -i /opt/controller/id -o IdentitiesOnly=yes -o UserKnownHostsFile=/opt/controller/known_hosts -o BatchMode=yes -p 2222 runner@127.0.0.1 '/bin/bash /testbed/ci/run.sh' 2>&1 | tee output/ci-run.log
status=${PIPESTATUS[0]}
printf 'SSH_CI_EXIT=%s\n' "$status"
exit "$status"", "workdir": "/testbed", "yield_time_ms": 30000, "max_output_tokens": 20000}
